function buildDeltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const journal = multisetDiff(before.journal, after.journal);
  const ping = multisetDiff(before.ping, after.ping);
  return {
    rels: [
      { rel: "journal", add: journal.add, del: journal.del },
      { rel: "ping", add: ping.add, del: ping.del },
    ],
    carryPending: journal.add.length > 0 || journal.del.length > 0,
  };
}

